import {VOICES,VOICE_KEY,PACK_KEY,PACK_FILES,PACK_CACHE,getVoice,hasPack,validVoice} from './voice-config.js';
let worker,sequence=0,pending=new Map(),loading=false,ready=false,message='内置听力和起步 20 词可直接使用三种男声。',error=false;
const generated=new Map();
export const cachedNatural=(text,voice)=>generated.get(voice+'\n'+text);
const notify=()=>{if(typeof window!=='undefined')window.dispatchEvent(new Event('yan-voice-change'));};
function request(type,data={}){
 return new Promise((resolve,reject)=>{
  if(!worker){worker=new Worker(new URL('./voice-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data:r})=>{const job=pending.get(r.id);if(r.type==='progress'){message=r.message;notify();return;}if(!job)return;clearTimeout(job.timer);pending.delete(r.id);if(r.type==='error')job.reject(Error(r.message));else job.resolve(r.buffer);};worker.onerror=()=>{for(const job of pending.values()){clearTimeout(job.timer);job.reject(Error('当前浏览器无法加载免费语音，请使用 Chrome / Edge 重试。'));}pending.clear();worker.terminate();worker=null;ready=false;};}
  const id=++sequence,timer=setTimeout(()=>{worker?.terminate();worker=null;ready=false;for(const job of pending.values()){clearTimeout(job.timer);job.reject(Error('准备声音超时，请检查网络后重试。'));}pending.clear();},type==='load'?20*60*1000:90*1000);
  pending.set(id,{resolve,reject,timer});worker.postMessage({id,type,...data});
 });
}
export async function enablePack(){if(loading)return;loading=true;error=false;message='正在准备免费语音包…';notify();try{await request('load');ready=true;try{localStorage.setItem(PACK_KEY,'1');}catch{}message='免费自然男声已就绪。词汇和例句在这台设备生成，无需 API。';}catch(e){error=true;message=e.message;}finally{loading=false;notify();}}
export async function naturalAudio(text,voice){const key=voice+'\n'+text;if(generated.has(key))return generated.get(key);if(!ready){const cache=await caches.open(PACK_CACHE);for(const url of PACK_FILES)if(!await cache.match(url)){try{localStorage.removeItem(PACK_KEY);}catch{}throw Error('语音包已被浏览器清理，请到“更多”重新下载。');}await request('load');ready=true;}const buffer=await request('speak',{text,voice});generated.set(key,buffer);if(generated.size>20)generated.delete(generated.keys().next().value);return buffer;}
export function chooseVoice(value){if(!validVoice(value))return false;try{localStorage.setItem(VOICE_KEY,value);}catch{}notify();return true;}
export function voiceSelect(listening=false){const choice=getVoice()==='device'&&listening?'M2':getVoice();return `<label>声音 <select data-voice-choice aria-label="学习声音">${VOICES.filter(([id])=>!listening||id!=='device').map(([id,label])=>`<option value="${id}" ${id===choice?'selected':''}>${label}</option>`).join('')}</select></label>`;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function voicePanel(){return `<section class="panel glass voice-panel"><span class="eyebrow">A VOICE BY YOUR SIDE</span><h2>选一个，陪你慢慢学</h2><p>你选中的男声 ②、④、⑤ 都在这里。听力可以直接切换；声音偏好会留在这台设备。</p><div class="speech-options">${voiceSelect()}<button type="button" class="btn secondary" data-action="voice-preview">试听这位男声</button><button type="button" class="btn ghost" data-action="speech-stop">停止</button></div><p class="caption" data-speech-status role="status"></p><details><summary>让完整词库和例句也用这个声音</summary><p>首次下载约 400 MB，建议连接 Wi-Fi。下载一次后在手机本地生成，无需付费 API、账号或电脑常开。速度与可用性取决于设备内存；不支持时仍可用设备语音。</p><p class="caption">语音资源来自 Hugging Face 与 unpkg；朗读文字不上传给它们。语音包缓存与学习记录分开，清理语音包不会删除进度。</p><div class="actions"><button type="button" class="btn secondary" data-action="voice-enable" ${loading?'disabled':''}>${loading?'正在准备…':hasPack()?'重新检查免费语音包':'下载免费语音包'}</button><button type="button" class="btn ghost" data-action="voice-remove" ${loading?'disabled':''}>移除语音包</button></div><p class="caption ${error?'voice-error':''}" data-voice-status role="status">${esc(message)}</p></details></section>`;}
export async function removePack(){if(loading)return;worker?.terminate();worker=null;ready=false;for(const job of pending.values()){clearTimeout(job.timer);job.reject(Error('语音包已移除。'));}pending.clear();try{localStorage.removeItem(PACK_KEY);await caches.delete('yan-natural-voice-pack-v1');message='已移除可选语音包，学习进度仍保留。';}catch{message='移除未完成，请重试。';}notify();}
